/* Honestly Zen Event Planning MVP — vanilla JS UI connected to the FastAPI/SQLite backend. */
'use strict';
const $=s=>document.querySelector(s);
const state={user:null,workspaces:[],ws:null,page:'dashboard',eventId:null,events:[],event:null,summary:null,meals:null,rows:[],lookup:[],search:'',filter:'All',sidebar:false,authMode:'login',busy:false,demoEnabled:false,publicDemo:false,platformBrand:null,_lastHash:'',_routeTrail:[],_routeBack:false};
const PATHS={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',check:'<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0-3 3v12a3 3 0 0 0 3 3h15a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2H5a3 3 0 0 1 0-6"/><path d="M16 14h4"/>',store:'<path d="m3 9 2-6h14l2 6v12H3V9ZM3 9h18M9 21v-8h6v8"/>',chart:'<path d="M4 21V9M10 21V3M16 21v-7M22 21V6M2 21h22"/>',kanban:'<rect x="3" y="3" width="7" height="18" rx="1"/><rect x="14" y="3" width="7" height="10" rx="1"/>',contacts:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 14a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM5 18c0-2 6-2 6 0M15 9h4M15 13h4M15 17h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 13.5V10.5l2-1-2-4-2 1-2-2H9l-2 2-2-1-2 4 2 1v3l-2 1 2 4 2-1 2 2h6l2-2 2 1 2-4z"/>',plus:'<path d="M12 5v14M5 12h14"/>',back:'<path d="m15 18-6-6 6-6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',file:'<path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM13 2v7h7M8 14h8M8 18h8"/>',spark:'<path d="m12 3 2.1 6.9L21 12l-6.9 2.1L12 21l-2.1-6.9L3 12l6.9-2.1z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 7 10-7"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',building:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M9 21v-4h6v4M8 7h1M15 7h1M8 11h1M15 11h1"/>',person:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
function icon(k){return `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" fill="none" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[k]||PATHS.grid}</svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const money=(v)=>new Intl.NumberFormat('en-CA',{style:'currency',currency:state.ws?.currency||'CAD',maximumFractionDigits:0}).format(Number(v)||0);
const fmtDate=v=>{if(!v)return 'Not set';let d=new Date(v+'T12:00:00');return Number.isNaN(d.getTime())?v:d.toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'})};
const short=v=>String(v||'').slice(0,10);
const titleCase=s=>s==='business'?'Business':'Personal';
function badge(s){let c={'Confirmed':'good','Done':'good','Won':'good','Booked':'good','Planning':'blue','Qualified':'blue','In Progress':'blue','Proposal':'blue','Pending':'warn','Draft':'warn','Open':'warn','New':'warn','High':'red','Declined':'red','Lost':'red','Cancelled':'red'}[s]||'';return `<span class="badge ${c}">${esc(s)}</span>`}
function toast(s){let e=$('#toast');e.textContent=s;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),3500)}
async function api(path,opt={}){let method=opt.method||'GET';let resp=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(opt.body?{'Content-Type':'application/json'}:{}),...(opt.headers||{})},body:opt.body?JSON.stringify(opt.body):undefined});let json;try{json=await resp.json()}catch{json={}};if(!resp.ok){if(resp.status===401&&state.user){state.user=null;renderAuth()}throw Error(typeof json.detail==='string'?json.detail:(json.detail?.[0]?.msg||'Request failed'))}return json}
const prefix=()=>`/w/${state.ws.id}`;
const evpath=()=>`${prefix()}/events/${state.eventId}`;
const eventPages=['overview','details','guests','tasks','budget','eventVendors','schedule','operations','gallery','registry','website','agencyDesk','checkin'];
const isEventPage=()=>eventPages.includes(state.page);
function route(){
 const current=location.hash;
 if(state._lastHash && state._lastHash!==current && !state._routeBack && /^#\//.test(state._lastHash)){
  state._routeTrail.push(state._lastHash);
  if(state._routeTrail.length>40)state._routeTrail.shift();
 }
 state._routeBack=false;state._lastHash=current;
 let p=current.slice(2).split('/');if(p[0]){let ws=state.workspaces.find(w=>w.id===p[0]);if(ws)state.ws=ws;}
 state.page=p[1]||'dashboard';state.eventId=p[2]||null;if(isEventPage()&&!state.eventId)state.page='events';
}
function breadcrumbModel(){
 const w=state.ws?.id||'';
 const label={dashboard:'Dashboard',events:'Events',pipeline:'Leads & pipeline',contacts:'Contacts',vendors:'Vendor directory',reports:'Reports',settings:'Settings',branding:'Branding Studio',paymentOnboarding:'Agency payments',overview:'Command center',details:'Event details',guests:'Guests & RSVP',tasks:'Tasks',budget:'Budget',eventVendors:'Event vendors',schedule:'Schedule',checkin:'Check-in',operations:'Event operations',gallery:'Photo gallery',registry:'Gift registry',website:'Event website',agencyDesk:'Agency client desk',agencyClients:'Clients & projects',team:'Team & roles',platform:'Platform Admin',billing:'Subscription',myAccount:'My Account',support:'Support Center',supportInbox:'Support inbox',help:'Help Center',diyStart:'Party wizard',diyPlanner:'DIY Planning Studio',partyMarket:'Vendor marketplace',partyVendor:'My vendor listings',partyDeals:'Quotes & contracts',partyCommunity:'Party community',partyTrends:'Trendboard',partyModeration:'Marketplace moderation',growthInbox:'Notifications',growthNews:'News',vendorDashboard:'Vendor dashboard',growthAdmin:'Publishing'};
 const parents=[{text:state.ws?.name||'Workspace',page:'dashboard'}];
 const isEvent=!!state.eventId&&(isEventPage()||state.page==='diyPlanner');
 if(isEvent){parents.push({text:'Events',page:'events'});if(state.page!=='overview')parents.push({text:state.event?.name||'Event',page:'overview',id:state.eventId});}
 else if(state.page==='partyDeals')parents.push({text:'Vendor marketplace',page:'partyMarket'});
 else if(state.page==='diyPlanner')parents.push({text:'Events',page:'events'});
 const current=label[state.page]||'Dashboard';
 if(state.page==='dashboard')return {parents:[],current};
 return {parents,current};
}
function breadcrumbs(){
 const b=breadcrumbModel(),id=state.ws?.id||'';
 const link=x=>{const hash='#/'+encodeURIComponent(id)+'/'+encodeURIComponent(x.page)+(x.id?'/'+encodeURIComponent(x.id):'');return '<a href="'+hash+'">'+esc(x.text)+'</a>'};
 return '<nav class="app-breadcrumbs" aria-label="Breadcrumb"><button type="button" class="app-go-back" onclick="eventosGoBack()" title="Go back one step" aria-label="Go back one step">'+icon('back')+'<span>Back</span></button>'+b.parents.map(x=>link(x)+'<span aria-hidden="true" class="crumb-sep">/</span>').join('')+'<span aria-current="page" class="crumb-current">'+esc(b.current)+'</span></nav>';
}
function eventosGoBack(){
 const last=state._routeTrail.pop();if(last&&last!==location.hash){state._routeBack=true;location.hash=last;return}
 const b=breadcrumbModel();const target=b.parents[b.parents.length-1];go(target?.page||'dashboard',target?.id);
}
window.eventosGoBack=eventosGoBack;
function appBrand(){const site=state.platformBrand||{},name=site.site_name||'Honestly Zen Event Planning',logo=site.logo_url;return '<a href="/" class="brand app-brand" title="Go to home">'+(logo?'<span class="app-brand-image"><img src="'+esc(logo)+'" alt="" onerror="this.parentElement.hidden=true"></span>':'<span class="logo-mark">✦</span>')+'<span class="brand-text">'+esc(name)+'</span></a>'}
async function loadPublicBrand(){try{let d=await api('/public/site-brand');if(d&&typeof d==='object')state.platformBrand=d}catch(e){state.platformBrand=null}}

function go(page,id){window.EventOSOperations?.stop?.();state.search='';state.filter='All';state.guestGroupFilter='All';state.guestCategoryFilter='All';state.guestSelected=new Set();state.sidebar=false;let w=state.ws?.id||'';let h=`#/${w}/${page}${id?'/'+id:''}`;if(location.hash===h){refresh()}else{location.hash=h}}
window.addEventListener('hashchange',()=>{if(window.EventOSAccount?.renderEmailConfirmation?.()||window.EventOSPhase7?.renderAuthRoute?.())return;route();refresh()});
async function start(){
const incoming=new URLSearchParams(location.search);
state.selectedLandingPlan=['free','pro','business'].includes(incoming.get('plan'))?incoming.get('plan'):null;
state.selectedLandingCycle=['monthly','yearly'].includes(incoming.get('cycle'))?incoming.get('cycle'):'monthly';
state.selectedLandingWorkspaceType=['personal','business'].includes(incoming.get('workspace_type'))?incoming.get('workspace_type'):'personal';
state.billingReturn=['return','cancel'].includes(incoming.get('billing'))?incoming.get('billing'):null;
if(incoming.get('mode')==='signup')state.authMode='signup';
 await loadPublicBrand();
if(window.EventOSAccount?.renderEmailConfirmation?.()||window.EventOSPhase7?.renderAuthRoute?.())return;try{let config=await api('/config');state.demoEnabled=!!config.demo_enabled;state.publicDemo=!!config.public_demo;state.requireAccessCode=!!config.signup_access_code_required;state.verifyEmailRequired=!!config.email_verification_required;state.recoveryEnabled=!!config.password_recovery_enabled;}catch{}try{let a=await api('/me');state.user=a.user;state.workspaces=a.workspaces;state.ws=a.workspaces[0];route();if(!state.ws)throw Error('No workspaces available');
if((state.selectedLandingPlan&&state.selectedLandingPlan!=='free')||state.billingReturn){
 state.page='billing';go('billing')
}else await refresh()}catch(e){if(!state.user)renderAuth();else{toast(e.message);renderAuth()}}}
async function refresh(){if(!state.user||!state.ws)return;const seq=Date.now()+Math.random();refresh.seq=seq;try{let events=await api(prefix()+'/events');if(seq!==refresh.seq)return;state.events=events;state.workspaceFeatures=(await api(prefix()+'/features')).features;state.event=state.eventId?events.find(x=>x.id===state.eventId):null;let p=state.page;if(isEventPage()&&!state.event){state.page='events';p='events'};if(p==='dashboard')state.rows=await api(prefix()+'/summary');else if(p==='overview')state.summary=await api(evpath()+'/command-center');else if(p==='operations'){[state.operations,state.opsMessages]=await Promise.all([api(evpath()+'/operations'),api(evpath()+'/messages')]);}else if(p==='gallery')state.galleryData=await api(evpath()+'/gallery');else if(p==='registry')state.registryData=await api(evpath()+'/registry');else if(p==='website')state.websiteData=await api(evpath()+'/website');else if(p==='agencyDesk'){[state.agencyData,state.agencyAdvanced]=await Promise.all([api(evpath()+'/agency'),api(evpath()+'/agency/advanced')]);}else if(p==='agencyClients')state.agencyClients=await api(prefix()+'/agency');else if(p==='guests'){const [guests,summary]=await Promise.all([api(evpath()+'/guests'),api(evpath()+'/command-center')]);state.rows=guests;state.meals=summary.meals||null;}else if(p==='tasks')state.rows=await api(evpath()+'/tasks');else if(p==='budget')state.rows=await api(evpath()+'/budget');else if(p==='eventVendors'){state.rows=await api(evpath()+'/vendors');state.lookup=await api(prefix()+'/vendors')}else if(p==='vendors')state.rows=await api(prefix()+'/vendors');else if(p==='pipeline')state.rows=await api(prefix()+'/leads');else if(p==='contacts')state.rows=await api(prefix()+'/contacts');else if(p==='schedule')state.rows=await api(evpath()+'/schedule');else if(p==='checkin')state.rows=await api(evpath()+'/checkin');else if(p==='branding')state.brandingData=await api(prefix()+'/branding');else if(p==='paymentOnboarding')state.paymentOnboarding=await api(prefix()+'/payment-onboarding');else if(p==='reports'){[state.rows,state.opsRollup]=await Promise.all([api(prefix()+'/summary'),api(prefix()+'/operations/summary')]);}else if(p==='team'){state.team=await api(prefix()+'/team');state.teamCodes=state.ws?.role==='owner'?await api(prefix()+'/team/access-codes'):[];}else if(p==='platform'){[state.platform,state.platformBillingAudit,state.platformReadiness,state.platformBackups,state.platformLaunch,state.platformStudio,state.platformAnalytics]=await Promise.all([api('/platform/overview'),api('/platform/billing-audit'),api('/platform/readiness'),api('/platform/backups'),api('/platform/launch-readiness'),api('/platform/studio'),api('/platform/analytics').catch(err=>{console.warn('Platform analytics unavailable',err);return null})]);}else if(['diyStart','diyPlanner'].includes(p))await window.EventOSDIY?.load(p);else if(['partyMarket','partyVendor','partyDeals','partyCommunity','partyTrends','partyModeration'].includes(p))await window.EventOSParty?.load(p);else if(['growthInbox','vendorDashboard','growthNews','growthAdmin'].includes(p))await window.EventOSGrowth?.load(p);else if(p==='monetization')await window.HZMonetization?.load();else if(p==='vendorOffers'){await window.HZMonetization?.vendorLoad();state.vendorMonetListings=await api('/party/vendors/mine');}else if(p==='billing')state.billing=await api(prefix()+'/billing');else if(p==='myAccount')[state.accountOverview,state.accountEmailPrefs]=await Promise.all([api('/account/overview'),api('/account/email-preferences')]);else if(p==='support'||p==='supportInbox'){if(p==='supportInbox')state.supportAdmin=await api('/platform/support');else state.supportData=await api('/support/tickets');state.supportTicket=state.eventId?await api('/support/tickets/'+encodeURIComponent(state.eventId)):null;}if(seq!==refresh.seq)return;render()}catch(e){toast(e.message);console.error(e)}}
function initials(name){return (name||'U').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function navButton(page,label,ic,id){return `<button type="button" class="nav-link ${state.page===page?'active':''}" onclick="go('${page}'${id?`,'${id}'`:''})">${icon(ic)}${esc(label)}</button>`}
function sidebar(){let isEv=(isEventPage()||(state.page==='diyPlanner'&&state.eventId))&&state.event;return `<div class="mobile-overlay ${state.sidebar?'show':''}" onclick="state.sidebar=false;render()"></div><aside class="sidebar ${state.sidebar?'open':''}">${appBrand()}<button class="ws-picker" onclick="openModal('switchWorkspace')"><span class="ws-icon">${icon(state.ws.type==='personal'?'person':'building')}</span><span class="two-line"><div class="ellipsis" style="font-weight:800;font-size:12px">${esc(state.ws.name)}</div><div class="tiny-note">${titleCase(state.ws.type)} workspace</div></span><span class="muted">⌄</span></button>${isEv?`<div class="nav-group"><div class="nav-head">WORKSPACE</div>${navButton('events','All events','back')}${navButton('dashboard','Dashboard','grid')}</div><div class="nav-group"><div class="nav-head">EVENT WORKSPACE</div>${navButton('overview','Command center','grid',state.eventId)}${navButton('details','Event details','file',state.eventId)}${navButton('guests','Guests & RSVP','users',state.eventId)}${navButton('tasks','Tasks & checklist','check',state.eventId)}${navButton('budget','Budget & expenses','wallet',state.eventId)}${navButton('diyPlanner','DIY planning studio','spark',state.eventId)}${navButton('eventVendors','Event vendors','store',state.eventId)}${navButton('schedule','Schedule','clock',state.eventId)}${navButton('checkin','Event-day check-in','check',state.eventId)}${state.workspaceFeatures?.operations!==false?navButton('operations','Event operations','users',state.eventId):''}${state.workspaceFeatures?.gallery!==false?navButton('gallery','Photo gallery','grid',state.eventId):''}${state.workspaceFeatures?.registry!==false?navButton('registry','Gift registry','store',state.eventId):''}${state.workspaceFeatures?.websites!==false?navButton('website','Event website','spark',state.eventId):''}${state.ws.type==='business'&&state.workspaceFeatures?.agency!==false?navButton('agencyDesk','Agency client desk','contacts',state.eventId):''}</div>`:`<div class="nav-group"><div class="nav-head">WORKSPACE</div>${navButton('dashboard','Dashboard','grid')}${navButton('diyStart','Plan a party · Wizard','spark')}${navButton('diyPlanner','DIY planning hub','check')}${navButton('events',state.ws.type==='personal'?'My events':'Events','calendar')}${state.ws.type==='business'?navButton('pipeline','Leads & pipeline','kanban')+(state.workspaceFeatures?.agency!==false?navButton('agencyClients','Clients & projects','contacts'):''):''}${navButton('contacts','Contacts','contacts')}${navButton('vendors','Vendor directory','store')}${navButton('reports','Reports','chart')}${navButton('team','Team & roles','users')}</div>`}<div class="nav-group"><div class="nav-head">PARTY PLANNING</div>${navButton('partyMarket','Vendor marketplace','store')}${navButton('partyDeals','Quotes & contracts','file')}${navButton('partyCommunity','Community','users')}${navButton('partyTrends','Trendboard','spark')}${navButton('partyVendor','List your service','plus')}${navButton('vendorDashboard','Vendor Dashboard','chart')+navButton('vendorOffers','Paid growth & offers','wallet')}${state.user.platform_role==='admin'?navButton('partyModeration','Listing approvals & moderation','settings'):''}</div><div class="nav-group"><div class="nav-head">ACCOUNT</div>${state.user.platform_role==='admin'?navButton('platform','Platform Admin','settings')+navButton('monetization','Monetization Center','wallet'):''}${navButton('myAccount','My account','person')}${navButton('growthInbox','Notifications','mail')}${navButton('growthNews','News & Blog','file')}${navButton('billing','Subscription & usage','wallet')}${navButton('help','Help Center','file')}${navButton('support','Support Center','mail')}${state.user.platform_role==='admin'?navButton('supportInbox','Support inbox','mail')+navButton('growthAdmin','Announcements & Growth','chart'):''}${state.ws.type==='business'?navButton('branding','Branding Studio','spark')+(state.ws.role==='owner'?navButton('paymentOnboarding','Agency payments','wallet'):''):''}${navButton('settings','Settings','settings')}</div><div class="sidebar-foot"><div style="display:flex;align-items:center;gap:9px"><span class="avatar">${esc(initials(state.user.full_name))}</span><span><strong style="font-size:12px">${esc(state.user.full_name)}</strong><div class="tiny-note">Signed in</div></span></div><button class="nav-link" style="margin-top:12px" onclick="logout()">${icon('logout')}Sign out</button></div></aside>`}
function shell(body){let label={dashboard:'Dashboard',events:'Events',pipeline:'Pipeline',contacts:'Contacts',vendors:'Vendors',reports:'Reports',settings:'Settings',branding:'Branding Studio',paymentOnboarding:'Agency payments',overview:'Command center',details:'Details',guests:'Guests',tasks:'Tasks',budget:'Budget',eventVendors:'Event vendors',schedule:'Schedule',checkin:'Event-day check-in',operations:'Event operations',gallery:'Photo Gallery',registry:'Gift Registry',website:'Event Website',agencyDesk:'Agency Client Desk',agencyClients:'Clients & Projects',team:'Team & roles',platform:'Platform Admin',billing:'Subscription & usage',myAccount:'My account',support:'Support Center',supportInbox:'Support inbox',help:'Help Center',diyStart:'Party Planning Wizard',diyPlanner:'DIY Planning Studio',partyMarket:'Vendor Marketplace',partyDeals:'Quotes & Contracts',partyVendor:'Vendor Listings',partyCommunity:'Party Community',partyTrends:'Trendboard',partyModeration:'Listing Approvals & Moderation',growthInbox:'Notifications',growthNews:'News & Blog',vendorDashboard:'Vendor Dashboard',growthAdmin:'Communications & Growth',monetization:'Monetization Center',vendorOffers:'Paid Growth & Offers'}[state.page]||'Dashboard';let ev=(isEventPage()||(state.page==='diyPlanner'&&state.eventId))&&state.event;$('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main"><header class="topbar"><div class="top-start"><button class="mobile-button" onclick="state.sidebar=!state.sidebar;render()" aria-label="Open navigation">${icon('menu')}</button>${breadcrumbs()}</div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('en-CA',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span><button class="btn primary" onclick="openModal('event')">${icon('plus')}<span class="desktop-label"> New event</span></button><button class="avatar as-avatar-button" type="button" onclick="go('myAccount')" title="My account" aria-label="My account">${esc(initials(state.user.full_name))}</button></div></header><div class="content">${state.publicDemo?`<div class="public-demo-banner"><strong>Temporary phone demo</strong> — sample data only. Changes may reset after the server sleeps or redeploys.</div>`:''}${body}</div></main></div>`;document.title=label+' · Honestly Zen Event Planning';window.EventOSGrowth?.afterShell()}
function head(title,sub,buttons=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div>${buttons?`<div class="head-actions">${buttons}</div>`:''}</div>`}
function button(text,action,primary=true){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${primary?icon('plus'):''}${esc(text)}</button>`}
function stat(name,val,hint,ic){return `<div class="card kpi"><div class="over"><span>${esc(name)}</span>${icon(ic||'grid')}</div><div class="value">${val}</div><div class="under">${esc(hint||'')}</div></div>`}
function empty(name,sub,cta=''){return `<div class="empty"><div class="emoji">✧</div><strong>${esc(name)}</strong>${esc(sub)}${cta?`<div style="margin-top:16px">${cta}</div>`:''}</div>`}
function dashboard(){const d=state.rows||{},evts=d.upcoming||[],isBiz=state.ws.type==='business';let first=evts[0]||state.events[0];return `${head(isBiz?'Business command center':'Your event dashboard',isBiz?'A clear view of events, opportunities and what needs attention.':'A calmer way to stay on top of every celebration.',button('Create event',"openModal('event')"))}<div class="grid kpis">${stat('Active events',d.active_events||0,'Current workspace','calendar')}${isBiz?stat('Open leads',d.open_leads||0,'Sales opportunities','users'):stat('Events planned',state.events.length,'All time','spark')}${isBiz?stat('Pipeline value',money(d.pipeline_value||0),'Open sales pipeline','wallet'):stat('Upcoming events',evts.length,'Next planned events','clock')}${stat('Open tasks',d.open_tasks||0,'Across events','check')}</div><div class="grid two-col m-top"><div class="card pad"><div class="section-title"><h2>Upcoming events</h2><button class="subtle-link" onclick="go('events')">View all →</button></div>${evts.length?evts.map(e=>`<div class="event-row"><div class="left"><div class="event-icon">${icon('calendar')}</div><div style="min-width:0"><div class="event-title">${esc(e.name)}</div><div class="tiny-note">${esc(fmtDate(e.start_date))} · ${esc(e.location||e.type)}</div></div></div><div class="row-actions">${badge(e.status)}<button class="btn tiny" onclick="go('overview','${e.id}')">Open</button></div></div>`).join(''):empty('Nothing on the calendar','Create your first event to get started.')}</div><div class="card pad"><div class="section-title"><h2>Quick actions</h2></div><div class="grid" style="gap:10px"><button class="btn" onclick="openModal('event')">${icon('calendar')} Create another event</button>${first?`<button class="btn" onclick="go('guests','${first.id}')">${icon('users')} Manage guest list</button><button class="btn" onclick="go('tasks','${first.id}')">${icon('check')} Review planning tasks</button>`:''}${isBiz?`<button class="btn" onclick="openModal('lead')">${icon('plus')} Add a new lead</button>`:''}</div><hr class="divider"><p class="small-note">Your information is saved to the configured Honestly Zen Event Planning database. Personal and Business workspaces have separate records.</p></div></div>${first?`<div class="card pad m-top"><div class="section-title"><h2>Featured event</h2><button class="subtle-link" onclick="go('overview','${first.id}')">Open workspace →</button></div><div class="event-row"><div class="left"><div class="event-mark">✦</div><div><div class="event-title">${esc(first.name)}</div><div class="small-note">${esc(first.type)} · ${esc(first.location||'Location not set')}</div></div></div><div>${badge(first.status)}</div></div></div>`:''}`}
function eventsPage(){let data=state.events.filter(e=>[e.name,e.type,e.location].join(' ').toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='All'||e.status===state.filter));return `${head('Events',`${state.events.length} event${state.events.length===1?'':'s'} in ${state.ws.name}`,button('New event',"openModal('event')"))}<div class="toolbar"><input class="search" placeholder="Search events…" aria-label="Search events" value="${esc(state.search)}" oninput="searchRows(this.value)"><select class="select" aria-label="Event status" onchange="state.filter=this.value;render()">${['All','Draft','Planning','Confirmed','Completed','Cancelled'].map(s=>`<option ${state.filter===s?'selected':''}>${s}</option>`).join('')}</select></div>${data.length?`<div class="grid three-col">${data.map(e=>`<article class="card card-event" role="button" tabindex="0" onclick="go('overview','${e.id}')" onkeydown="if(event.key==='Enter')go('overview','${e.id}')"><div style="display:flex;justify-content:space-between;align-items:center"><div class="event-mark">✦</div>${badge(e.status)}</div><div><h3>${esc(e.name)}</h3><p class="tiny-note" style="margin:0">${esc(e.type)}</p></div><div class="meta"><span>${icon('calendar')} ${esc(fmtDate(e.start_date))}</span><span>${icon('location')} ${esc(e.location||'TBD')}</span></div><div class="mini-stats"><span>${e.invitees} invitees</span><span>${e.confirmed_seats} seats confirmed</span><span>${money(e.budget)} budget</span></div><div class="hz-row-actions"><span style="color:var(--teal);font-size:12px;font-weight:750">Open event →</span><button type="button" class="btn tiny hz-danger" onclick="event.stopPropagation();archiveEvent('${e.id}')">Archive</button></div></article>`).join('')}</div>`:empty('No events match','Adjust your search or create a new event.',button('Create event',"openModal('event')"))}`}
function overview(){return renderEventCommandCenter(state.summary||{},state.event)}
function details(){let e=state.event;return `${head('Event details','Basic information and scope for your event.',button('Edit event',"openModal('editEvent')"))}<div class="card pad"><div class="grid two-col"><div>${[['Event name',e.name],['Type',e.type],['Starts',fmtDate(e.start_date)],['Ends',fmtDate(e.end_date)],['Status',e.status]].map(x=>`<div class="attention-row"><span class="muted">${x[0]}</span><strong>${esc(x[1]||'Not set')}</strong></div>`).join('')}</div><div>${[['Venue or location',e.location||'TBD'],['Expected guests',e.expected_guests],['Budget',money(e.budget)],['Parent event',e.parent_event_id?'Linked to a parent event':'Independent event']].map(x=>`<div class="attention-row"><span class="muted">${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div></div></div>`}
function guestMealSummary(){
  const meals=state.meals;
  if(!meals?.enabled)return '';
  return `<section class="card pad guest-meal-summary" aria-label="Meal preference counts">
    <div class="section-title"><h2>Meal preferences</h2><span class="tiny-note">${esc(meals.selected)} selected</span></div>
    <div class="guest-meal-grid">${meals.choices.map(choice=>`<div class="guest-meal-count"><span>${esc(choice.name)}</span><strong>${esc(choice.count)}</strong></div>`).join('')}</div>
    <p class="small-note">Only selected meals from confirmed RSVPs are counted. Blank preferences are excluded.</p>
  </section>`;
}
function guestSelection(id,checked){if(!state.guestSelected)state.guestSelected=new Set();if(checked)state.guestSelected.add(id);else state.guestSelected.delete(id);const n=document.getElementById('selectedGuestCount');if(n)n.textContent=state.guestSelected.size+' selected'}
function selectAllGuestRows(checked){const items=[...document.querySelectorAll('[data-guest-select]')];items.forEach(n=>{n.checked=checked;guestSelection(n.dataset.guestSelect,checked)})}
function guests(){
 let all=state.rows||[],group=state.guestGroupFilter||'All',category=state.guestCategoryFilter||'All';
 let groups=[...new Set(all.map(g=>g.group_name).filter(Boolean))].sort(),categories=[...new Set(all.map(g=>g.category||'General'))].sort();
 let rows=all.filter(g=>[g.name,g.email,g.phone,g.group_name,g.category,g.notes].join(' ').toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='All'||g.rsvp===state.filter)&&(group==='All'||g.group_name===group)&&(category==='All'||(g.category||'General')===category));
 const attending=all.filter(g=>g.rsvp==='Confirmed').reduce((sum,g)=>sum+Number(g.reported_attending??g.party_size),0);
 const reserved=all.reduce((sum,g)=>sum+Number(g.party_size||0),0);
 return `${head('Guests & RSVP',`${all.length} invitation records · ${attending} attending · ${reserved} reserved seats`,button('Add guest',"openModal('guest')")+button('Design invitation',"openInvitationDesigner()",false)+button('Edit RSVP form',"openRSVPBuilder()",false)+button('Preview invitation',"openInvitationDesigner('preview')",false)+button('Preview RSVP',"openRSVPBuilder('preview')",false)+button('View answers',"viewRSVPAnswers()",false)+button('Import Excel / CSV',"openModal('importGuests')",false)+button('Import phone contacts',"openPhoneContactImport()",false))}
 <div class="grid three-col" style="margin-bottom:18px">${stat('Invitations',all.length,'Guest households / groups','users')}${stat('Actual attending',attending,'Submitted guest counts when available','check')}${stat('Pending replies',all.filter(g=>g.rsvp==='Pending').length,'Waiting for response','clock')}</div>
 ${guestMealSummary()}
 <div class="toolbar guest-crm-toolbar">
   <input class="search" placeholder="Search names, notes, email, group…" value="${esc(state.search)}" oninput="searchRows(this.value)">
   <select class="select" aria-label="Filter by RSVP" onchange="state.filter=this.value;render()">${['All','Pending','Confirmed','Maybe','Declined'].map(s=>`<option ${state.filter===s?'selected':''}>${s}</option>`).join('')}</select>
   <select class="select" aria-label="Filter by group" onchange="state.guestGroupFilter=this.value;render()"><option value="All">All groups</option>${groups.map(x=>`<option value="${esc(x)}" ${group===x?'selected':''}>${esc(x)}</option>`).join('')}</select>
   <select class="select" aria-label="Filter by category" onchange="state.guestCategoryFilter=this.value;render()"><option value="All">All categories</option>${categories.map(x=>`<option value="${esc(x)}" ${category===x?'selected':''}>${esc(x)}</option>`).join('')}</select>
   <button class="btn" type="button" onclick="openModal('bulkGuests')">Bulk edit <span id="selectedGuestCount">${state.guestSelected?.size||0} selected</span></button>
   <button class="btn" type="button" onclick="location.href='/api'+evpath()+'/guests/export.xlsx'">${icon('file')} Export Excel</button>
   <button class="btn" type="button" onclick="location.href='/api'+evpath()+'/guests/export.csv'">${icon('file')} Export CSV</button>
 </div>
 <div class="card table-wrap guest-crm-table">${rows.length?`<table class="table"><thead><tr><th><input type="checkbox" aria-label="Select all visible guests" onchange="selectAllGuestRows(this.checked)"></th><th>Guest</th><th>Group / category</th><th>Seats</th><th>Attending</th><th>Response</th><th>Invitation</th><th></th></tr></thead><tbody>${rows.map(g=>`<tr>
 <td><input type="checkbox" data-guest-select="${g.id}" aria-label="Select ${esc(g.name)}" ${state.guestSelected?.has(g.id)?'checked':''} onchange="guestSelection('${g.id}',this.checked)"></td>
 <td><strong>${esc(g.name)}</strong><div class="tiny-note">${esc([g.email,g.phone].filter(Boolean).join(' · ')||'No contact provided')}</div>${g.notes?`<div class="guest-crm-note" title="${esc(g.notes)}">Private note: ${esc(g.notes)}</div>`:''}</td>
 <td>${esc(g.group_name||'—')}<div class="tiny-note">${esc(g.category||'General')}</div></td>
 <td>${Number(g.party_size)||1}</td>
 <td>${g.rsvp==='Confirmed'?(g.reported_attending??g.party_size):'—'}${g.reported_plus_one?'<div class="tiny-note">Includes +1</div>':''}</td>
 <td><select class="select" aria-label="RSVP for ${esc(g.name)}" onchange="updateGuest('${g.id}',this.value)" style="height:33px;padding:4px 6px">${['Pending','Confirmed','Maybe','Declined'].map(st=>`<option ${st===g.rsvp?'selected':''}>${st}</option>`).join('')}</select>${g.rsvp_submitted_at?`<div class="tiny-note">Replied ${esc(g.rsvp_submitted_at.slice(0,10))}</div>`:''}</td>
 <td><button class="btn tiny" type="button" onclick="copyInvite('${g.invitation_token}')">Copy RSVP link</button></td>
 <td><button class="btn tiny" type="button" onclick="openModal('editGuest','${g.id}')">Edit</button></td>
 </tr>`).join('')}</tbody></table>`:empty('No guests found','Add someone or adjust your filters.')}</div>
 <p class="small-note">RSVP links are private to each invitation. Bulk changes apply only to selected guests; no invitations are sent automatically.</p>`;
}
function tasks(){let data=(state.rows||[]).filter(t=>[t.title,t.assigned_to].join(' ').toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='All'||t.status===state.filter));return `${head('Tasks & checklist','Manage preparation, ownership and deadlines.',button('Add task',"openModal('task')"))}<div class="toolbar"><input class="search" value="${esc(state.search)}" placeholder="Search tasks…" oninput="searchRows(this.value)"><select class="select" onchange="state.filter=this.value;render()">${['All','Open','In Progress','Done'].map(s=>`<option ${state.filter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="card table-wrap">${data.length?`<table class="table"><thead><tr><th>Complete</th><th>Task</th><th>Due date</th><th>Priority</th><th>Assigned to</th><th>Status</th><th></th></tr></thead><tbody>${data.map(t=>`<tr><td><input type="checkbox" class="check" aria-label="Complete ${esc(t.title)}" ${t.status==='Done'?'checked':''} onchange="updateTask('${t.id}',this.checked?'Done':'Open')"></td><td><strong style="${t.status==='Done'?'text-decoration:line-through;color:#9ea9b5':''}">${esc(t.title)}</strong></td><td>${esc(t.due_date||'—')}</td><td>${badge(t.priority)}</td><td>${esc(t.assigned_to||'Unassigned')}</td><td>${badge(t.status)}</td><td><button class="btn tiny" onclick="openModal('editTask','${t.id}')">Edit</button></td></tr>`).join('')}</tbody></table>`:empty('No tasks yet','Start with the next action that moves your event forward.')}</div>`}
function budget(){let arr=state.rows||[],sum=k=>arr.reduce((a,b)=>a+Number(b[k]||0),0),ev=state.event,remaining=ev.budget-sum('committed');return `${head('Budget & expenses',`All amounts in ${state.ws.currency}. Estimates, commitments, actual costs and payments are tracked separately.`,button('Add expense',"openModal('budget')"))}<div class="grid kpis">${stat('Event budget',money(ev.budget),'Target budget','wallet')}${stat('Committed',money(sum('committed')),'Supplier commitments','check')}${stat('Actual cost',money(sum('actual')),'Accrued / invoiced','chart')}${stat('Remaining',money(remaining),'Target less committed','wallet')}</div><div class="card table-wrap m-top">${arr.length?`<table class="table"><thead><tr><th>Budget item</th><th>Category</th><th>Estimated</th><th>Committed</th><th>Actual</th><th>Paid</th><th></th></tr></thead><tbody>${arr.map(b=>`<tr><td><strong>${esc(b.name)}</strong></td><td>${esc(b.category)}</td><td>${money(b.estimated)}</td><td>${money(b.committed)}</td><td>${money(b.actual)}</td><td>${money(b.paid)}</td><td><button class="btn tiny" onclick="openModal('editBudget','${b.id}')">Edit</button></td></tr>`).join('')}</tbody></table>`:empty('No budget items','Add a planned or committed cost to begin tracking your budget.')}</div><p class="small-note">Remaining budget = event budget minus committed amount. Actual and paid are separate measures and are not added again to commitments.</p>`}
function vendors(){let arr=state.rows||[];return `${head('Vendor directory',`Suppliers available to ${state.ws.name}.`,button('Add vendor',"openModal('vendor')"))}<div class="grid three-col">${arr.length?arr.map(v=>`<article class="card pad"><div class="event-mark" style="margin-bottom:14px">${icon('store')}</div><strong style="font-size:15px">${esc(v.name)}</strong><p class="small-note">${esc(v.category)}</p><div class="tiny-note">${esc(v.email||'No email')} ${v.phone?'· '+esc(v.phone):''}</div><p class="tiny-note">${esc(v.notes||'')}</p></article>`).join(''):empty('No vendors yet','Add a supplier to your directory.')}</div>`}
function eventVendors(){let rows=state.rows||[],available=state.lookup||[];return `${head('Event vendors','Connect your workspace suppliers to this event.',button('Assign vendor',"openModal('assignVendor')"))}<div class="card table-wrap">${rows.length?`<table class="table"><thead><tr><th>Vendor</th><th>Category</th><th>Scope</th><th>Status</th><th>Committed cost</th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(v.name)}</strong><div class="tiny-note">${esc(v.email)}</div></td><td>${esc(v.category)}</td><td>${esc(v.scope)}</td><td>${badge(v.status)}</td><td>${money(v.committed)}</td></tr>`).join('')}</tbody></table>`:empty('No suppliers assigned','Assign a supplier from the vendor directory.')}</div><div class="card pad m-top"><div class="section-title"><h2>Workspace vendor directory</h2></div><p class="small-note">${available.length} vendor records available for assignment. <button class="subtle-link" onclick="go('vendors')">Manage vendor directory →</button></p></div>`}
function schedule(){let rows=state.rows||[];return `${head('Event schedule','A simple run of show and milestone timeline.',button('Add schedule item',"openModal('schedule')"))}<div class="card pad">${rows.length?rows.map(s=>`<div class="timeline-row"><div class="time">${esc(s.start_at.replace('T',' '))}</div><div><strong>${esc(s.title)}</strong><div class="tiny-note">${s.end_at?'Until '+esc(s.end_at.replace('T',' '))+' · ':''}${esc(s.location||'Location TBD')}</div></div></div>`).join(''):empty('No schedule items yet','Add a session, ceremony, milestone, or event-day activity.')}</div>`}
function pipeline(){let leads=state.rows||[],stages=['New','Qualified','Proposal','Negotiation','Won','Lost'];return `${head('Leads & pipeline',`${leads.length} opportunities · ${money(leads.filter(l=>!['Won','Lost'].includes(l.stage)).reduce((a,b)=>a+b.value,0))} open pipeline`,button('New lead',"openModal('lead')"))}<div class="kanban">${stages.map(stage=>{let grp=leads.filter(l=>l.stage===stage);return `<div class="kanban-col"><div class="kanban-head"><span>${esc(stage)}</span><span class="badge">${grp.length}</span></div>${grp.map(l=>`<div class="deal"><strong>${esc(l.title)}</strong><p>${esc(l.client_name)}</p><div class="deal-foot"><span>${money(l.value)}</span>${l.event_id?'<span class="badge good">Booked</span>':''}</div><select class="select" aria-label="Move ${esc(l.title)} to stage" onchange="moveLead('${l.id}',this.value)">${stages.map(s=>`<option ${stage===s?'selected':''}>${s}</option>`).join('')}</select>${l.stage==='Won'&&!l.event_id?`<button class="btn tiny full" style="margin-top:8px" onclick="convertLead('${l.id}')">Create event from lead</button>`:l.event_id?`<button class="btn tiny full" style="margin-top:8px" onclick="go('overview','${l.event_id}')">Open linked event</button>`:`<button class="btn tiny full" style="margin-top:8px" onclick="convertLead('${l.id}')">Win & create event</button>`}</div>`).join('')||'<p class="tiny-note">No opportunities</p>'}</div>`}).join('')}</div><p class="small-note">Moving an opportunity into “Won” does not automatically create an event. Use “Create event from lead” when the booking is ready.</p>`}
function contacts(){let list=(state.rows||[]).filter(c=>[c.name,c.email].join(' ').toLowerCase().includes(state.search.toLowerCase()));return `${head('CRM & contacts','People and organizations associated with this workspace.',button('New contact',"openModal('contact')"))}<div class="toolbar"><input class="search" value="${esc(state.search)}" placeholder="Search contacts…" oninput="searchRows(this.value)"></div><div class="card table-wrap">${list.length?`<table class="table"><thead><tr><th>Name</th><th>Category</th><th>Email</th><th>Phone</th><th>Notes</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.kind)}</td><td>${esc(c.email||'—')}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.notes||'—')}</td></tr>`).join('')}</tbody></table>`:empty('No contacts yet','Add a client or collaborator to your contacts.')}</div>`}
function teamPage(){
 let roster=state.team||[],teamCodes=state.teamCodes||[];
 return head('Workspace team & roles','Grant access to registered Honestly Zen Event Planning users. Owners manage team membership.')+
 '<div class="card pad"><h2>Team members</h2>'+roster.map(u=>
 '<div class="attention-row"><div><strong>'+esc(u.full_name)+'</strong><p class="tiny-note">'+esc(u.email)+'</p></div><div>'+esc(u.role)+' '+
 (state.ws.role==='owner'&&u.id!==state.user.id?'<button class="btn tiny" onclick="editTeamRole('+"'"+u.id+"'"+')">Change role</button> <button class="btn tiny" onclick="removeTeamMember('+"'"+u.id+"'"+')">Remove</button>':'')+'</div></div>').join('')+
 (state.ws.role==='owner'?'<button class="btn primary" onclick="addTeamMember()">Add registered team member</button>':'')+
 '<p class="small-note">Editors may update event records and check in guests. Viewers are read-only. You can invite an existing account directly or issue a staff code for someone signing up for the first time.</p></div>'+
 (state.ws.role==='owner'?'<div class="card pad m-top"><h2>Role-based team access codes</h2><p class="small-note">Create an Editor or Viewer code, then share it privately. The recipient can enter this code during signup or from Workspace Settings to join this workspace. Codes are shown once.</p><button class="btn primary" type="button" onclick="issueTeamCode()">Generate team code</button>'+teamCodes.map(x=>'<div class="attention-row"><div><strong>'+esc(x.role)+'</strong><div class="tiny-note">'+x.uses+'/'+x.max_uses+' redeemed'+(x.active?' · Active':' · Disabled')+'</div></div><button type="button" class="btn tiny" onclick="toggleTeamCode(\''+x.id+'\','+(!x.active)+')">'+(x.active?'Disable':'Enable')+'</button></div>').join('')+'</div>':'');
}
async function issueTeamCode(){
 let role=prompt('New staff access code role: editor or viewer','editor');if(!role)return;
 if(!['editor','viewer'].includes(role)){toast('Choose editor or viewer');return}
 let count=Number(prompt('How many people can redeem this code? (1–100)','1'));
 if(!Number.isInteger(count)||count<1||count>100){toast('Choose a whole number from 1 to 100');return}
 try{
   const made=await api(prefix()+'/team/access-codes',{method:'POST',body:{role,max_uses:count}});
   const code=made.access_code;
   state.teamCodes=await api(prefix()+'/team/access-codes');render();
   const result=prompt('NEW TEAM ACCESS CODE — copy it now. It cannot be viewed again.',code);
   if(result===null){toast('Code generated. It cannot be retrieved after closing this dialog.');return}
   try{await navigator.clipboard.writeText(code);toast('Staff access code copied')}catch{toast('Copy the displayed code securely')}
 }catch(e){toast(e.message)}
}
async function toggleTeamCode(id,active){
 if(!confirm(active?'Reactivate this staff code?':'Disable this staff code?'))return;
 try{await api(prefix()+'/team/access-codes/'+id,{method:'PATCH',body:{active}});state.teamCodes=await api(prefix()+'/team/access-codes');render();toast('Staff code updated')}catch(e){toast(e.message)}
}
async function joinTeamWithCode(){
 const code=prompt('Enter your organization team access code');if(!code)return;
 try{const result=await api('/access/join-workspace',{method:'POST',body:{access_code:code}});
   const me=await api('/me');state.workspaces=me.workspaces;state.ws=me.workspaces.find(w=>w.id===result.workspace_id)||state.ws;
   toast('Joined workspace as '+result.role);go('dashboard');
 }catch(e){toast(e.message)}
}
async function addTeamMember(){
 let email=prompt('Registered team member email');if(!email)return;
 let role=prompt('Role: editor or viewer','editor');if(!role)return;
 try{await api(prefix()+'/team',{method:'POST',body:{email,role}});toast('Team member added');await refresh()}catch(e){toast(e.message)}
}
async function editTeamRole(id){
 let role=prompt('New role: owner, editor or viewer','editor');if(!role)return;
 try{await api(prefix()+'/team/'+id,{method:'PATCH',body:{role}});toast('Role updated');await refresh()}catch(e){toast(e.message)}
}
async function removeTeamMember(id){
 if(!confirm('Remove this team member from the workspace?'))return;
 try{await api(prefix()+'/team/'+id,{method:'DELETE'});toast('Team member removed');await refresh()}catch(e){toast(e.message)}
}
