function formField(label,name,value='',type='text',wide=false,attrs=''){return `<label class="field ${wide?'wide':''}"><span>${esc(label)}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs} ${type==='number'?'min="0" step="any"':''}></label>`}
function formSelect(label,name,options,value='',wide=false){return `<label class="field ${wide?'wide':''}"><span>${esc(label)}</span><select name="${name}">${options.map(o=>{let [val,txt]=Array.isArray(o)?o:[o,o];return `<option value="${esc(val)}" ${val===value?'selected':''}>${esc(txt)}</option>`}).join('')}</select></label>`}
function modal(title,body,kind,id='',submitLabel='Save'){let note=`<p class="tiny-note" style="margin:0 0 18px">Changes are saved to your Honestly Zen Event Planning database.</p>`;$('#modalRoot').innerHTML=`<div class="modal-overlay" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><header class="modal-head"><h2 id="modal-heading">${esc(title)}</h2><button type="button" class="xclose" onclick="closeModal()" aria-label="Close">×</button></header><div class="modal-body">${note}<form id="recordForm" onsubmit="saveForm(event,'${kind}','${id}')"><div class="inline-fields">${body}</div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn primary">${esc(submitLabel)}</button></div></form></div></section></div>`;$('#recordForm input,#recordForm select')?.focus()}
