function openModal(kind,id=''){
  if(kind==='event'&&state.ws?.type==='personal'&&window.EventOSBranding){window.EventOSBranding.wizard();return}
 let row=(Array.isArray(state.rows)?state.rows:[]).find(x=>x.id===id)||{},e=kind==='editEvent'?state.event:{},body='',title='',label='Save';
 const eventTypes=['Birthday','Wedding','Anniversary','Conference','Corporate meeting','Festival','Concert','Fundraiser','Baby shower','Private party','Client event','Other'];
 if(kind==='event'||kind==='editEvent'){title=kind==='event'?'Create event':'Edit event';label=kind==='event'?'Create event':'Save changes';body=formField('Event name','name',e.name||'','text',true,'required')+formSelect('Event type','type',eventTypes,e.type||'Birthday')+formField('Start date','start_date',short(e.start_date)||new Date().toISOString().slice(0,10),'date',false,'required')+formField('End date (optional)','end_date',short(e.end_date)||'','date')+formField('Location / venue','location',e.location||'','text',true)+formField('Expected guests','expected_guests',e.expected_guests??0,'number')+formField(`Budget (${state.ws.currency})`,'budget',e.budget??0,'number')+formSelect('Status','status',['Draft','Planning','Confirmed','Completed','Cancelled'],e.status||'Draft')+formSelect('Parent event (optional)','parent_event_id', [['','None — independent event'],...state.events.filter(x=>x.id!==state.eventId||kind==='event').map(x=>[x.id,x.name])],e.parent_event_id||'')}
 if(kind==='guest'||kind==='editGuest'){title=kind==='guest'?'Add guest':'Edit guest';body=formField('Guest name','name',row.name||'','text',true,'required')+formField('Email (optional)','email',row.email||'','email')+formField('Phone (optional)','phone',row.phone||'','tel')+formField('Seats in invitation','party_size',row.party_size||1,'number')+formField('Invitation group','group_name',row.group_name||'')+formField('Guest category','category',row.category||'General')+formSelect('RSVP','rsvp',['Pending','Confirmed','Maybe','Declined'],row.rsvp||'Pending')+ `<label class="field wide"><span>Private CRM notes (not shown to guests)</span><textarea rows="3" maxlength="2000" name="notes">${esc(row.notes||'')}</textarea></label>`}
 if(kind==='task'||kind==='editTask'){title=kind==='task'?'Add planning task':'Edit task';body=formField('Task title','title',row.title||'','text',true,'required')+formField('Due date','due_date',short(row.due_date)||'','date')+formField('Assigned to','assigned_to',row.assigned_to||state.user.full_name)+formSelect('Priority','priority',['Low','Medium','High'],row.priority||'Medium')+formSelect('Status','status',['Open','In Progress','Done'],row.status||'Open')}
 if(kind==='budget'||kind==='editBudget'){title=kind==='budget'?'Add budget item':'Edit budget item';body=formField('Item name','name',row.name||'','text',true,'required')+formSelect('Category','category',['Venue','Food','Catering','Decor','AV','Staffing','Travel','Rentals','Gifts','Other'],row.category||'Other')+formField('Estimated','estimated',row.estimated||0,'number')+formField('Committed','committed',row.committed||0,'number')+formField('Actual','actual',row.actual||0,'number')+formField('Paid','paid',row.paid||0,'number')}
 if(kind==='vendor'){title='Add vendor';body=formField('Vendor name','name','','text',true,'required')+formField('Category','category','Catering')+formField('Email','email','','email')+formField('Phone','phone')+formField('Notes','notes','','text',true)}
 if(kind==='assignVendor'){title='Assign a vendor';if(!(state.lookup||[]).length){toast('Add a vendor to your workspace directory first.');go('vendors');return}body=formSelect('Vendor','vendor_id',state.lookup.map(v=>[v.id,v.name]),state.lookup[0]?.id,true)+formField('Scope of work','scope','','text',true)+formSelect('Booking status','status',['Shortlisted','Quote requested','Booked','Cancelled'],'Shortlisted')+formField('Committed cost','committed',0,'number')}
 if(kind==='lead'){title='New sales opportunity';body=formField('Opportunity name','title','','text',true,'required')+formField('Client / company name','client_name','','text',false,'required')+formField('Client email','client_email','','email')+formField('Expected value','value',0,'number')+formField('Expected event date','expected_date','','date')+formSelect('Pipeline stage','stage',['New','Qualified','Proposal','Negotiation','Won','Lost'],'New')}
 if(kind==='contact'){title='New contact';body=formField('Contact name','name','','text',true,'required')+formField('Email','email','','email')+formField('Phone','phone')+formSelect('Type','kind',['client','vendor','organizer','other'],'client')+formField('Notes','notes','','text',true)}
 if(kind==='schedule'){title='New schedule item';body=formField('Activity title','title','','text',true,'required')+formField('Start date / time','start_at','','datetime-local',false,'required')+formField('End date / time','end_at','','datetime-local')+formField('Location','location','','text',true)}
 if(kind==='workspace'){title='Create workspace';body=formField('Workspace name','name','','text',true,'required')+formSelect('Workspace mode','type',[['personal','Personal'],['business','Business']],'personal')+formSelect('Currency','currency',['CAD','USD','GBP','EUR','AUD','INR'],'CAD')+formField('Access code'+(state.requireAccessCode?' (required)':' (optional)'),'access_code','','text',true,state.requireAccessCode?'required':'')}
 if(kind==='switchWorkspace'){let box=`<div class="workspace-list">${state.workspaces.map(w=>`<button type="button" onclick="switchWorkspace('${w.id}')"><span><strong>${esc(w.name)}</strong><div class="tiny-note">${esc(titleCase(w.type))} · ${esc(w.role)}</div></span>${w.id===state.ws.id?'✓':'→'}</button>`).join('')}</div><button class="btn full" style="margin-top:20px" onclick="openModal('workspace')">${icon('plus')} Create new workspace</button>`;$('#modalRoot').innerHTML=`<div class="modal-overlay" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>Switch workspace</h2><button class="xclose" onclick="closeModal()">×</button></div><div class="modal-body">${box}</div></div></div>`;return}
 if(kind==='importGuests'){title='Import guests from Excel or CSV';body=`<label class="field wide"><span>Excel (.xlsx) or CSV with name, email, phone, party_size, group_name, category, notes, rsvp</span><input type="file" name="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" required></label><p class="small-note">Up to 1,000 guests per import. Existing guests are preserved. Repeated email, phone, or name within the same group will be skipped.</p>`;label='Import guests'}
 if(kind==='bulkGuests'){const count=state.guestSelected?.size||0;if(!count){toast('Select at least one guest first');return}title='Bulk update '+count+' guests';body=`<p class="small-note">Changes apply only to the selected guests in this event.</p>`+formSelect('Update field','field',[['group_name','Invitation group'],['category','Guest category'],['rsvp','RSVP status']],'group_name',true)+formField('New value','value','','text',true,'required maxlength="160"')+`<p class="small-note">For RSVP status, enter Pending, Confirmed, Maybe or Declined.</p>`;label='Update selected guests'}
 modal(title,body,kind,id,label)
}
function values(form){let d=Object.fromEntries(new FormData(form));for(let k of ['expected_guests','budget','party_size','estimated','committed','actual','paid','value'])if(k in d)d[k]=Number(d[k]);for(let k of ['end_date','parent_event_id','client_contact_id'])if(k in d&&d[k]==='')d[k]=null;return d}
async function saveForm(ev,kind,id){ev.preventDefault();if(state.busy)return;state.busy=true;let submit=ev.currentTarget.querySelector('[type=submit]');submit.disabled=true;try{let obj=values(ev.currentTarget),path='',method='POST';
 if(kind==='event'||kind==='editEvent'){path=kind==='event'?prefix()+'/events':evpath();if(kind==='editEvent')method='PATCH'}
 else if(kind==='guest'||kind==='editGuest'){path=kind==='guest'?evpath()+'/guests':`${prefix()}/guests/${id}`;if(kind==='editGuest')method='PATCH'}
 else if(kind==='task'||kind==='editTask'){path=kind==='task'?evpath()+'/tasks':`${prefix()}/tasks/${id}`;if(kind==='editTask')method='PATCH'}
 else if(kind==='budget'||kind==='editBudget'){path=kind==='budget'?evpath()+'/budget':`${prefix()}/budget/${id}`;if(kind==='editBudget')method='PATCH'}
 else if(kind==='vendor')path=prefix()+'/vendors';
 else if(kind==='assignVendor')path=evpath()+'/vendors';
 else if(kind==='lead')path=prefix()+'/leads';
 else if(kind==='contact')path=prefix()+'/contacts';
 else if(kind==='schedule')path=evpath()+'/schedule';
 else if(kind==='workspace')path='/workspaces';
 else if(kind==='bulkGuests'){
   const ids=[...(state.guestSelected||[])],field=obj.field,value=String(obj.value||'').trim();
   if(!['group_name','category','rsvp'].includes(field))throw Error('Choose a valid guest field');
   const result=await api(evpath()+'/guests/bulk',{method:'PATCH',body:{ids,changes:{[field]:value}}});
   state.guestSelected=new Set();closeModal();toast(result.updated+' guests updated');await refresh();return
 }
 else if(kind==='importGuests'){
  const file=ev.currentTarget.querySelector('input[type=file]').files[0];if(!file)throw Error('Select a CSV or Excel file');
  let result;
  if(file.name.toLowerCase().endsWith('.xlsx')){
   if(file.size>2*1024*1024)throw Error('Excel workbook must be under 2 MB');
   const bytes=new Uint8Array(await file.arrayBuffer());let encoded='';
   for(let i=0;i<bytes.length;i+=32768)encoded+=String.fromCharCode(...bytes.subarray(i,i+32768));
   result=await api(evpath()+'/guests/import.xlsx',{method:'POST',body:{data_base64:btoa(encoded)}});
  }else if(file.name.toLowerCase().endsWith('.csv')){
   let rows=parseCSV(await file.text());if(!rows.length)throw Error('CSV file is empty');
   let h=rows.shift().map(s=>s.toLowerCase().trim().replaceAll(' ','_'));
   if(!h.includes('name'))throw Error('CSV must contain a name column');
   if(rows.length>1000)throw Error('Import up to 1,000 rows per batch');
   let cols=['name','email','phone','party_size','group_name','category','notes','rsvp'];
   let mapped=rows.filter(r=>r.some(x=>x.trim())).map(r=>Object.fromEntries(cols.map(k=>[k,h.includes(k)?r[h.indexOf(k)]||'':'']))).map(x=>({...x,party_size:x.party_size||1,category:x.category||'General',rsvp:x.rsvp||'Pending'}));
   result=await api(evpath()+'/guests/import-reviewed',{method:'POST',body:{rows:mapped}});
  }else throw Error('Choose an .xlsx or .csv file');
  closeModal();toast(result.imported+' guests imported · '+result.duplicates_skipped+' duplicates skipped');await refresh();return
 }
 let result=await api(path,{method,body:obj});closeModal();if(kind==='workspace'){let m=await api('/me');state.workspaces=m.workspaces;state.ws=state.workspaces.find(w=>w.id===result.id);go('dashboard')}else if(kind==='event'){toast('Event created');go('overview',result.id)}else{toast('Changes saved');await refresh()}
 }catch(e){toast(e.message)}finally{state.busy=false;if(submit?.isConnected)submit.disabled=false}}
function parseCSV(text){let rows=[],r=[],s='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){s+='"';i++}else quote=!quote}else if(c===','&&!quote){r.push(s);s=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;r.push(s);rows.push(r);r=[];s=''}else s+=c}if(s||r.length){r.push(s);rows.push(r)}if(rows[0]&&rows[0][0])rows[0][0]=rows[0][0].replace(/^\ufeff/,'');return rows}
async function updateGuest(id,status){try{await api(`${prefix()}/guests/${id}`,{method:'PATCH',body:{rsvp:status}});toast('RSVP updated');refresh()}catch(e){toast(e.message);refresh()}}
async function updateTask(id,status){try{await api(`${prefix()}/tasks/${id}`,{method:'PATCH',body:{status}});toast('Task updated');refresh()}catch(e){toast(e.message);refresh()}}
async function moveLead(id,stage){try{await api(`${prefix()}/leads/${id}`,{method:'PATCH',body:{stage}});toast('Pipeline updated');refresh()}catch(e){toast(e.message);refresh()}}
