async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}state.user=null;state.ws=null;location.hash='';renderAuth()}
function renderAuth(){let register=state.authMode==='signup';$('#app').innerHTML=`<div class="auth-page"><aside class="auth-aside"><div><div class="brand"><div class="logo-mark">✦</div> Honestly Zen Event Planning</div><h1>Every event.<br>One place to<br>make it happen.</h1><p>Plan intimate celebrations and manage professional events using one flexible workspace.</p></div><p>Plan · Collaborate · Celebrate</p></aside><main class="auth-panel"><div class="auth-box"><div class="small-label" style="color:var(--teal);margin-bottom:12px">WELCOME TO HONESTLY ZEN</div><h2>${register?'Create your account':'Sign in to Honestly Zen'}</h2><p>${register?'Build your first planning workspace.':'Pick up right where your planning left off.'}</p><form onsubmit="submitAuth(event)">${register?formField('Your name','full_name','','text',true,'required')+formField('Workspace name (optional for team access codes)','workspace_name','','text',true,'')+formSelect('Workspace type','workspace_type',[['personal','Personal'],['business','Business']],state.selectedLandingWorkspaceType||'personal',true)+formField('Plan or staff access code'+(state.requireAccessCode?' (required)':' (optional)'),'access_code','','text',true,state.requireAccessCode?'required':'')+'<p class="tiny-note">Joining an existing organization? Enter its staff access code; you do not need to create a new workspace.</p>':''} ${register&&state.selectedLandingPlan?'<div class="phase7-signup-selection">Selected plan: <strong>'+esc(({free:'Starter',pro:'Pro',business:'Business'})[state.selectedLandingPlan])+'</strong>. You can review billing after registration.</div>':''}${formField('Email','email',(!register&&state.demoEnabled)?'demo@eventos.local':'','email',true,'required')}${formField('Password','password',(!register&&state.demoEnabled)?'EventOSdemo2026!':'','password',true,register?'required minlength="10"':'required')}<button type="submit" class="btn primary full" style="margin-top:6px">${register?'Create account & workspace':'Sign in'}</button></form><p class="phase7-back"><a href="/">← Back to Honestly Zen website</a></p><span class="switch">${register?'Already have an account?':'New to Honestly Zen?'} <button onclick="state.authMode='${register?'login':'signup'}';renderAuth()">${register?'Sign in':'Create account'}</button></span>${!register?'<div class="phase7-auth-links"><button type="button" onclick="phase7Forgot()">Forgot password?</button> <button type="button" onclick="phase7Resend()">Resend verification</button></div>':''}${!register&&state.demoEnabled?`<div class="demo-note"><strong>Explore the sample MVP</strong><br>Demo email: <code>demo@eventos.local</code><br>Demo password: <code>EventOSdemo2026!</code><br><span class="muted">${state.publicDemo?"Temporary demo: data may reset when the free server sleeps or restarts.":"Saved data persists across refreshes on this server."}</span></div>`:''}</div></main></div>`}
async function submitAuth(ev){ev.preventDefault();let form=ev.currentTarget;let data=values(form);try{let result=await api('/auth/'+(state.authMode==='signup'?'signup':'login'),{method:'POST',body:data});if(result.verification_required){state.authMode='login';renderAuth();toast('Account created. Check your inbox to verify your email before signing in.');return}let m=await api('/me');state.user=m.user;state.workspaces=m.workspaces;state.ws=m.workspaces[0];state.page='dashboard';state.eventId=null;
const selected=state.selectedLandingPlan;
if(selected&&selected!=='free')go('billing');else go('dashboard')
}catch(e){toast(e.message)}}
start();

async function archiveEvent(id){
 if(!confirm('Archive this event? It will be marked Cancelled. Guests, financial records and contracts stay in the database.'))return;
 try{await api(prefix()+'/events/'+encodeURIComponent(id),{method:'DELETE'});toast('Event archived — change the status filter to see it.');await refresh()}
 catch(e){toast(e.message)}
}
